INSERT INTO lesson_contents (id, lesson_id, type, title, order_index) VALUES (9, 26, 'grid', 'Kí hiệu về trường học', 1);
INSERT INTO content_items (content_id, title, description, image_url, keywords, order_index) VALUES
(9,'Bảng','Hai tay giống số 1 úp, đặt gần nhau trước mặt, đưa đồng thời hai tay vẽ một hình chữ nhật trước mặt.','/images/pages/page0176_img01.png','bảng,blackboard,trường học',1),
(9,'Bút chì','1. Tay phải giống số 1, đưa đầu ngón trỏ vào khe hở tay trái, xoay cổ tay phải qua lại. 2. Tay phải giống động tác cầm bút, gập cổ tay ra-vào đồng thời đưa tay sang phải.','/images/pages/page0176_img01.png','bút chì,pencil,đồ dùng học tập',2),
(9,'Viết','Tay phải giống động tác cầm bút, lòng bàn tay úp, gập cổ tay ra-vào đồng thời đưa tay sang phải.','/images/pages/page0176_img01.png','viết,write,hoạt động',3),
(9,'Học bài','1. Tay phải chụm lại, đặt chạm các đầu ngón tay vào giữa trán. 2. Hai tay khép, đặt trước ngực, tay phải đặt trên tay trái, đưa tay phải đặt áp dọc vào bàn tay trái.','/images/pages/page0176_img01.png','học bài,study,hoạt động',4),
(9,'Sách','Hai tay khép, lòng bàn tay hướng vào nhau, đặt chạm nhau trước ngực, mở hai tay ra (giống mở sách).','/images/pages/page0177_img01.png','sách,book,đồ dùng học tập',5),
(9,'Vở','Tay trái khép ngửa, tay phải giống động tác cầm bút viết lên lòng bàn tay trái.','/images/pages/page0177_img01.png','vở,notebook,đồ dùng học tập',6),
(9,'Tẩy','Tay phải nắm, đặt lên lòng bàn tay trái, di chuyển tay phải qua lại (giống tẩy bút chì).','/images/pages/page0177_img01.png','tẩy,eraser,đồ dùng học tập',7),
(9,'Thước','Tay trái khép ngửa, tay phải giống số 1, đặt lên lòng bàn tay trái, di chuyển dọc theo bàn tay trái.','/images/pages/page0177_img01.png','thước,ruler,đồ dùng học tập',8),
(9,'Kéo','Tay phải giống chữ V, đặt trước ngực, đóng mở hai ngón tay (giống kéo cắt).','/images/pages/page0178_img01.png','kéo,scissors,đồ dùng học tập',9),
(9,'Đọc','Hai tay mở, lòng bàn tay ngửa, đặt trước mặt, mắt nhìn vào hai tay.','/images/pages/page0178_img01.png','đọc,read,hoạt động',10),
(9,'Toán','Hai tay giống chữ V, đặt trước ngực, đưa hai tay chéo vào nhau (giống dấu nhân).','/images/pages/page0179_img01.png','toán,math,môn học',11),
(9,'Tiếng Việt','Tay phải giống chữ V, đặt trước ngực, lắc cổ tay. Sau đó tay phải giống chữ T, lắc cổ tay.','/images/pages/page0179_img01.png','tiếng Việt,Vietnamese,môn học',12),
(9,'Lớp học','Hai tay khép, lòng bàn tay hướng vào nhau, đặt trước ngực, đưa hai tay về phía trước tạo hình hộp.','/images/pages/page0180_img01.png','lớp học,classroom,trường học',13),
(9,'Trường học','1. Giống ký hiệu Lớp học. 2. Tay phải chụm lại, đặt chạm các đầu ngón tay vào giữa trán.','/images/pages/page0180_img01.png','trường học,school',14),
(9,'Bàn','Hai tay khép úp, đặt song song trước ngực, đưa hai tay sang hai bên.','/images/pages/page0181_img01.png','bàn,table,đồ dùng',15),
(9,'Ghế','Hai tay giống chữ H, đặt trước ngực, tay phải đặt trên tay trái.','/images/pages/page0181_img01.png','ghế,chair,đồ dùng',16),
(9,'Thi','Tay phải giống chữ T, đặt trước ngực, đưa mạnh tay về phía trước.','/images/pages/page0182_img01.png','thi,exam,hoạt động',17),
(9,'Điểm','Tay phải giống số 1, đặt chạm vào lòng bàn tay trái.','/images/pages/page0182_img01.png','điểm,score,trường học',18),
(9,'Giỏi','Tay phải nắm, ngón cái duỗi lên trên (like).','/images/pages/page0183_img01.png','giỏi,good,đánh giá',19),
(9,'Kém','Tay phải nắm, ngón cái duỗi xuống dưới (dislike).','/images/pages/page0183_img01.png','kém,bad,đánh giá',20);
INSERT INTO lesson_contents (id, lesson_id, type, title, order_index) VALUES (10, 27, 'grid', 'Kí hiệu về giao thông', 1);
INSERT INTO content_items (content_id, title, description, image_url, keywords, order_index) VALUES
(10,'Giao thông đường không','1. Hai tay khép hướng vào nhau, đặt trước ngực, đưa hai tay về phía trước và đan chéo nhau. 2. Tay phải nắm, ngón cái ngón trỏ và ngón út mở ra, đưa tay chếch lên trên và về phía trước.','/images/pages/page0197_img01.png','giao thông đường không,aviation,giao thông',1),
(10,'Xe thô','Tay phải giống chữ B, đặt trước ngực. Tay trái khum hơi mở ngửa, đặt chạm lên cạnh bàn tay phải, đưa đồng thời cả hai tay về phía trước.','/images/pages/page0197_img01.png','xe thô,cart,giao thông',2),
(10,'Tàu thuỷ','Hai tay khép khum ngửa, đặt trước ngực, chạm hai mép tay vào nhau, đưa tay về phía trước.','/images/pages/page0197_img01.png','tàu thuỷ,ship,giao thông',3),
(10,'Thuyền buồm','Tay trái khép ngửa, đặt trước ngực. Tay phải khép, đặt chạm cổ tay vào mép tay trái, đưa đồng thời cả hai tay về phía trước.','/images/pages/page0197_img01.png','thuyền buồm,sailboat,giao thông',4),
(10,'Xe đạp','Hai tay nắm, đặt trước ngực, xoay hai tay theo vòng tròn ngược chiều nhau (giống đạp xe).','/images/pages/page0198_img01.png','xe đạp,bicycle,giao thông',5),
(10,'Xe máy','Hai tay nắm, đặt trước ngực (giống cầm tay lái), xoay cổ tay phải về phía trước (giống vặn ga).','/images/pages/page0198_img01.png','xe máy,motorcycle,giao thông',6),
(10,'Ô tô','Hai tay nắm, đặt trước ngực (giống cầm vô lăng), xoay hai tay sang trái rồi sang phải.','/images/pages/page0198_img01.png','ô tô,car,giao thông',7),
(10,'Xe buýt','Giống ký hiệu Ô tô, sau đó hai tay khép, đặt trước ngực, đưa hai tay sang hai bên (thể hiện xe to).','/images/pages/page0198_img01.png','xe buýt,bus,giao thông',8),
(10,'Tàu hoả','Hai tay nắm, đặt trước ngực, di chuyển hai tay theo đường thẳng về phía trước, đồng thời xoay cánh tay.','/images/pages/page0199_img01.png','tàu hoả,train,giao thông',9),
(10,'Máy bay','Tay phải nắm, ngón cái ngón trỏ và ngón út mở ra (giống hình máy bay), đưa tay chếch lên trên.','/images/pages/page0199_img01.png','máy bay,airplane,giao thông',10),
(10,'Đi bộ','Hai tay giống chữ V, đặt úp trước ngực, di chuyển luân phiên hai tay về phía trước (giống bước chân).','/images/pages/page0200_img01.png','đi bộ,walk,hoạt động',11),
(10,'Đường','Hai tay khép, lòng bàn tay hướng vào nhau, đặt trước ngực, đưa đồng thời hai tay về phía trước.','/images/pages/page0200_img01.png','đường,road,giao thông',12);
INSERT INTO lesson_contents (id, lesson_id, type, title, order_index) VALUES (11, 28, 'grid', 'Kí hiệu về quê hương - đất nước', 1);
INSERT INTO content_items (content_id, title, description, image_url, keywords, order_index) VALUES
(11,'Việt Nam','Tay phải giống chữ V, đặt trước ngực, lắc cổ tay. Sau đó tay phải giống chữ N, lắc cổ tay.','/images/pages/page0209_img01.png','Việt Nam,Vietnam,quốc gia',1),
(11,'Hà Nội','Tay phải giống chữ H, đặt trước ngực, lắc cổ tay. Sau đó tay phải giống chữ N, lắc cổ tay.','/images/pages/page0209_img01.png','Hà Nội,Hanoi,thành phố',2),
(11,'Thành phố Hồ Chí Minh','Tay phải giống chữ H, đặt trước ngực, lắc cổ tay. Sau đó giống chữ C, lắc cổ tay. Cuối cùng giống chữ M, lắc cổ tay.','/images/pages/page0209_img01.png','Thành phố Hồ Chí Minh,HCMC,thành phố',3),
(11,'Đà Nẵng','Tay phải giống chữ Đ, đặt trước ngực, lắc cổ tay. Sau đó giống chữ N, lắc cổ tay.','/images/pages/page0210_img01.png','Đà Nẵng,Danang,thành phố',4),
(11,'Huế','Tay phải giống chữ H, đặt trước ngực, lắc cổ tay.','/images/pages/page0210_img01.png','Huế,Hue,thành phố',5),
(11,'Miền Bắc','Tay phải khép, đặt trước ngực, đưa tay lên trên.','/images/pages/page0211_img01.png','miền Bắc,North,vùng miền',6),
(11,'Miền Trung','Tay phải khép, đặt trước ngực, giữ nguyên vị trí ở giữa.','/images/pages/page0211_img01.png','miền Trung,Central,vùng miền',7),
(11,'Miền Nam','Tay phải khép, đặt trước ngực, đưa tay xuống dưới.','/images/pages/page0211_img01.png','miền Nam,South,vùng miền',8),
(11,'Quê hương','Tay phải khép khum, đặt trước ngực, đưa tay về phía trái tim.','/images/pages/page0212_img01.png','quê hương,homeland',9),
(11,'Nước','Tay phải giống chữ N, đặt trước ngực, lắc cổ tay sang phải.','/images/pages/page0212_img01.png','nước,country,quốc gia',10),
(11,'Thành phố','Hai tay khép, đặt trước ngực, đưa hai tay lên cao tạo hình nhà cao tầng.','/images/pages/page0213_img01.png','thành phố,city',11),
(11,'Nông thôn','Hai tay mở, đặt trước ngực, đưa sang hai bên (thể hiện không gian rộng).','/images/pages/page0213_img01.png','nông thôn,countryside',12);
